import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except (TypeError, ValueError):
        return v is None


def _attrs_equal(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def run(inputs: dict) -> dict:
    dim_df = inputs["DIM_PRODUCT"].copy()
    stg_df = inputs["STG_PRODUCT"].copy()

    # Build working list of dict records from existing DIM_PRODUCT
    records = dim_df.to_dict("records")

    # Map product_id -> reference to the current (is_current==1) row dict
    current_map = {}
    for rec in records:
        if rec.get("is_current") == 1:
            pid = rec.get("product_id")
            current_map[pid] = rec

    # Sort staged rows by product_id, update_date ascending (not deduplicated)
    stg_sorted = stg_df.sort_values(
        by=["product_id", "update_date"],
        ascending=[True, True],
        kind="mergesort",  # stable sort to preserve original relative order on ties
    )

    for _, s in stg_sorted.iterrows():
        pid = s["product_id"]
        s_category = s["category"]
        s_price_band = s["price_band"]
        s_update_date = s["update_date"]

        current = current_map.get(pid)

        if current is None:
            new_row = {
                "product_id": pid,
                "category": s_category,
                "price_band": s_price_band,
                "eff_start_date": s_update_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            records.append(new_row)
            current_map[pid] = new_row
        else:
            cat_changed = not _attrs_equal(current.get("category"), s_category)
            pb_changed = not _attrs_equal(current.get("price_band"), s_price_band)
            if cat_changed or pb_changed:
                current["eff_end_date"] = s_update_date
                current["is_current"] = 0

                new_row = {
                    "product_id": pid,
                    "category": s_category,
                    "price_band": s_price_band,
                    "eff_start_date": s_update_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                records.append(new_row)
                current_map[pid] = new_row
            # else: no-op, unchanged record does not create a version

    out_cols = [
        "product_id",
        "category",
        "price_band",
        "eff_start_date",
        "eff_end_date",
        "is_current",
    ]

    if records:
        out_df = pd.DataFrame(records, columns=out_cols)
    else:
        out_df = pd.DataFrame(columns=out_cols)

    # Preserve dtypes as closely as possible to the original DIM_PRODUCT schema
    if "product_id" in dim_df.columns:
        out_df["product_id"] = out_df["product_id"].astype(dim_df["product_id"].dtype)
    if "is_current" in dim_df.columns:
        out_df["is_current"] = out_df["is_current"].astype(dim_df["is_current"].dtype)

    return {"dim_product_out": out_df}
